#include <stdio.h>
#include <unistd.h>
#include <sys/wait.h>

int main(void)
{
    int p[2];
    char buf[10];
    int n;

    pipe(p);
    if (fork() == 0) {
        close(p[0]);
        write(p[1], "hi\n", 3);
        return 0;
    }
    close(p[1]);
    n = read(p[0], buf, sizeof buf - 1);
    buf[n] = '\0';
    printf("%s", buf);
    wait(NULL);
    return 0;
}
